mapper.select:
SELECT a.*
FROM sys_audit_log a
LEFT JOIN sys_dept d ON d.dept_id = a.actor_dept_id
LEFT JOIN sys_user u ON u.user_id = a.actor_id

     AND a.module = #{module} 
     AND a.action = #{action} 
     AND a.resource_type = #{resourceType} 
     AND a.resource_id = #{resourceId} 
     AND a.actor LIKE CONCAT('%', #{actor}, '%') 
     AND a.status = #{status} 
     AND a.created_at >= #{fromTime} 
     AND a.created_at < #{toTime} 

    ${params.dataScope}

ORDER BY a.id DESC
